var i=`0309-kavarma`;var n=`world-0309`;var a=`BG`;var o=`eastern-europe`;var r=4;var s=88;var l={en:`Kavarma`,ua:`Каварма`};var u={en:`A traditional Bulgaria dish made with pork shoulder, yellow onion, red bell pepper, button mushroom. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Болгарія. Основні інгредієнти: свиняча лопатка, жовта цибуля, червоний солодкий перець, печериця. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`pork-shoulder`,620,`g`],[`extra-virgin-olive-oil`,55,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,220,`g`],[`red-bell-pepper`,240,`g`],[`button-mushroom`,180,`g`],[`sweet-paprika`,7,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`tomato-passata`,260,`g`],[`dry-white-wine`,110,`ml`],[`table-salt`,null,`to_taste`]]}];var m={slug:i,id:n,country:`BG`,region:o,servings:4,minutes:88,title:l,text:u,steps:d};export{a as country,m as default,n as id,s as minutes,o as region,r as servings,i as slug,d as steps,u as text,l as title};